  </div>
      <p class="purchases__unauth-text">
        Чтобы увидеть содержание страницы, вам необходимо Авторизоваться
      </p>
      <button class="purchases__unauth-btn" @click="router.push('/auth')">
        Авторизоваться
      </button>
    </div>

      <template v-else>
    <!-- Tabs -->
    <div class="purchases__tabs">
      <button
        v-for="tab in tabs"
        :key="tab.id"
        class="purchases__tab"
        :class="{ active: activeTab === tab.id }"
        @click="activeTab = tab.id"
      >
        <span v-if="tab.icon" v-html="tab.icon" class="purchases__tab-icon" />
        {{ tab.name }}
      </button>
    </div>

    <!-- Загрузка -->
    <div v-if="store.loading" class="purchases__loading">
      <div class="purchases__spinner" />
    </div>

    <!-- Список покупок -->
    <div class="purchases__list" v-else-if="filteredPurchases.length > 0">
      <div
        v-for="item in filteredPurchases"
        :key="item.id"
        class="purchases__card"
        @click="router.push(`/product/${item.products.id}`)"
      >
        <!-- Таймер бейдж -->
        <div
          v-if="item.status === 'reserved'"
          class="purchases__card-badge badge--reserved"
        >
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none">
            <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm.5-13H11v6l5.25 3.15.75-1.23-4.5-2.67V7z" fill="white"/>
          </svg>
          <span>{{ getTimer(item.id) }}</span>
        </div>

        <!-- Фото -->
        <div class="purchases__card-img">
          <img :src="item.products.image" :alt="item.products.name" />
        </div>

        <!-- Инфо -->
        <div class="purchases__card-info">
          <p class="purchases__card-name">{{ item.products.name }}</p>
          <span class="purchases__card-price">
            {{ item.products.price.toLocaleString() }} ₸
          </span>

          <!-- Зарезервировано: локация -->
          <div class="purchases__card-location" v-if="item.status === 'reserved' && item.products.location">
            <svg width="10" height="10" viewBox="0 0 24 24" fill="none">
              <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z" fill="#848484"/>
            </svg>
            <span>{{ item.products.location }}</span>
          </div>

          <!-- Купленные: дата -->
          <div class="purchases__card-date" v-if="item.status === 'bought'">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none">
              <path d="M20.25 4.5H3.75C3.33579 4.5 3 4.83579 3 5.25V18.75C3 19.1642 3.33579 19.5 3.75 19.5H20.25C20.6642 19.5 21 19.1642 21 18.75V5.25C21 4.83579 20.6642 4.5 20.25 4.5Z" stroke="#848484" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
              <path d="M15.75 8.25C15.75 9.24456 15.3549 10.1984 14.6517 10.9017C13.9484 11.6049 12.9946 12 12 12C11.0054 12 10.0516 11.6049 9.34835 10.9017C8.64509 10.1984 8.25 9.24456 8.25 8.25" stroke="#848484" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
            </svg>
            <span>{{ formatDate(item.created_at) }}</span>
