    <!-- Bottom Nav -->
    <div class="purchases__nav">
      <button
        v-for="navTab in navTabs"
        :key="navTab.id"
        class="purchases__nav-btn"
        :class="{ active: navTab.id === 'purchases' }"
        @click="navigate(navTab.id)"
      >
        <span v-html="navTab.icon" />
        <span>{{ navTab.name }}</span>
      </button>
