  </div>
  
</template>

<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useRouter } from 'vue-router'
import { useCatalogueStore } from '../stores/catalogueStore'
import { supabase } from '../services/supabase'
import { getAuth, onAuthStateChanged } from 'firebase/auth'


const router = useRouter()
const store = useCatalogueStore()
const activeTab = ref('all')
const isAuthorized = ref(false) 

// Таймеры для каждой покупки: { [purchaseId]: secondsLeft }
const timers = ref({})
const intervals = {}


onMounted(() => {
  const auth = getAuth()
  onAuthStateChanged(auth, (user) => {
    isAuthorized.value = !!user
    if (isAuthorized.value) {
      store.fetchPurchases().then(() => initTimers())
    }
  })
})

onUnmounted(() => {
  Object.values(intervals).forEach(clearInterval)
})

function initTimers() {
  store.purchases.forEach(item => {
    if (item.status === 'reserved') {
      // Считаем сколько времени прошло с момента создания
      const created = new Date(item.created_at).getTime()
      const now = Date.now()
      const elapsed = Math.floor((now - created) / 1000)
      const total = 59 * 60 // 59 минут
      const left = Math.max(total - elapsed, 0)

      timers.value[item.id] = left

      if (left > 0) {
        intervals[item.id] = setInterval(() => {
          timers.value[item.id]--
          if (timers.value[item.id] <= 0) {
            clearInterval(intervals[item.id])
            // Авто-удаление из списка
            store.fetchPurchases()
          }
        }, 1000)
      }
    }
  })
}

function getTimer(id) {
  const s = timers.value[id] ?? 0
  const h = Math.floor(s / 3600)
  const m = Math.floor((s % 3600) / 60)
  const sec = s % 60
  return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`
}

async function cancelReserve(purchaseId) {
  clearInterval(intervals[purchaseId])
  delete timers.value[purchaseId]

  const { error } = await supabase
    .from('purchases')
    .delete()
    .eq('id', purchaseId)

  if (!error) {
    await store.fetchPurchases()
    initTimers()
  }
}

const tabs = [
  { id: 'all', name: 'Все', icon: null },
  {
    id: 'reserved',
    name: 'Зарезервированные',
    icon: `<svg width="16" height="16" viewBox="0 0 24 24" fill="none"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm.5-13H11v6l5.25 3.15.75-1.23-4.5-2.67V7z" fill="currentColor"/></svg>`
  },
  {
    id: 'bought',
    name: 'Купленные',
    icon: `<svg width="16" height="16" viewBox="0 0 24 24" fill="none"><path d="M20.25 4.5H3.75C3.33579 4.5 3 4.83579 3 5.25V18.75C3 19.1642 3.33579 19.5 3.75 19.5H20.25C20.6642 19.5 21 19.1642 21 18.75V5.25C21 4.83579 20.6642 4.5 20.25 4.5Z" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/><path d="M15.75 8.25C15.75 9.24456 15.3549 10.1984 14.6517 10.9017C13.9484 11.6049 12.9946 12 12 12C11.0054 12 10.0516 11.6049 9.34835 10.9017C8.64509 10.1984 8.25 9.24456 8.25 8.25" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`
  }
]

const filteredPurchases = computed(() => {
  if (activeTab.value === 'all') return store.purchases
  return store.purchases.filter(p => p.status === activeTab.value)
})

function formatDate(dateStr) {
  if (!dateStr) return ''
  const d = new Date(dateStr)
  const day = String(d.getDate()).padStart(2, '0')
  const month = String(d.getMonth() + 1).padStart(2, '0')
  const year = d.getFullYear()
  const hours = String(d.getHours()).padStart(2, '0')
  const mins = String(d.getMinutes()).padStart(2, '0')
  return `${day}.${month}.${year}, ${hours}:${mins}`
}

function navigate(tabId) {
  const routes = {
    catalogue: '/catalogue', favorites: '/favorites',
    funds: '/funds', purchases: '/purchases', profile: '/profile',
  }
  if (routes[tabId]) router.push(routes[tabId])
}

